private ReviewPo buildReview(RoutePo route, long globalVersion, WeatherVersions versions,
                             Long forecastVersion, List<ZonePo> activeZones, String requestId) {
    Set<String> hits = new TreeSet<>();
    List<WeatherViolation> violations = new ArrayList<>();
    // snapshot
    ObjectNode snapshot = objectMapper.createObjectNode();
    snapshot.put("weatherVersion", versions.weatherVersion());
    if (forecastVersion != null) snapshot.put("forecastVersion", forecastVersion); else snapshot.putNull("forecastVersion");
    snapshot.put("dutyVersion", versions.dutyVersion());
    ArrayNode zonesNode = snapshot.putArray("zones");
    for (ZonePo zone : activeZones) {
        if (!Geometry.polylineHitsRectangle(route.points(), zone.xMin(), zone.yMin(), zone.xMax(), zone.yMax())) continue;
        List<WeatherMinimaPo> minima = weatherRepo.findMinima(zone.zoneId());
        if (minima.isEmpty()) { hits.add(zone.zoneId()); continue; }
        if (forecastVersion == null) throw new ApiException(422, "FORECAST_MISSING", "航线经过配置了气象最低标准的区域 " + zone.zoneId() + "，必须提交预测气象版本");
        List<WeatherForecastPo> forecasts = weatherRepo.findForecasts(forecastVersion, zone.zoneId());
        ObjectNode zoneNode = zonesNode.addObject();
        zoneNode.put("zoneId", zone.zoneId());
        ArrayNode minimaNode = zoneNode.putArray("minima");
        ArrayNode forecastNode = zoneNode.putArray("forecasts");
        for (WeatherMinimaPo m : minima) {
            minimaNode.addObject()...put values;
            WeatherForecastPo covering = findCovering(forecasts, m);
            if (covering == null) throw new ApiException(422, "FORECAST_MISSING", "区域 " + zone.zoneId() + " 时段 [" + m.windowStart() + "," + m.windowEnd() + ") 缺预测");
            forecastNode.addObject()...;
            if (covering.visibilityM() < m.minVisibilityM()) violations.add(new WeatherViolation(zone.zoneId(), m.windowStart(), m.windowEnd(), METRIC_VISIBILITY, covering.visibilityM(), m.minVisibilityM()));
            if (covering.cloudBaseM() < m.minCloudBaseM()) violations.add(...);
        }
    }
    String conclusion = !hits.isEmpty() ? BLOCKED : (!violations.isEmpty() ? WEATHER_BLOCKED : CLEAR);
    String reviewId = "rv_" + UUID.randomUUID();
    return new ReviewPo(reviewId, route.routeId(), route.version(), globalVersion,
        versions.weatherVersion(), forecastVersion, versions.dutyVersion(),
        conclusion, new ArrayList<>(hits), List.copyOf(violations), snapshot.toString()... 
