public ReviewDiagnosticsDto getReviewDiagnostics(String reviewId) {
    return txTemplate.execute(status -> {
        ReviewPo po = reviewRepo.findReview(reviewId);
        if (po == null) throw 404;
        RoutePo route = routeRepo.findRoute(po.routeId());
        long globalVersion = airspaceRepo.getGlobalVersion();
        WeatherVersions versions = weatherRepo.getVersions();
        List<VersionDiagnosticDto> dims = new ArrayList<>();
        dims.add(new VersionDiagnosticDto("ROUTE", (long) po.routeVersion(), route == null ? null : (long) route.version(), route == null || route.version() != po.routeVersion()));
        dims.add(new VersionDiagnosticDto("AIRSPACE", po.airspaceVersion(), globalVersion, globalVersion != po.airspaceVersion()));
        dims.add(new VersionDiagnosticDto("WEATHER_MINIMA", po.weatherVersion(), versions.weatherVersion(), versions.weatherVersion() != po.weatherVersion()));
        dims.add(new VersionDiagnosticDto("FORECAST", po.forecastVersion(), versions.forecastVersion(), po.forecastVersion() != null && versions.forecastVersion() != po.forecastVersion()));
        dims.add(new VersionDiagnosticDto("DUTY", po.dutyVersion(), versions.dutyVersion(), versions.dutyVersion() != po.dutyVersion()));
        boolean stale = dims.stream().anyMatch(d -> Boolean.TRUE.equals(d.stale()));
        return new ReviewDiagnosticsDto(po.reviewId(), po.conclusion(), stale, dims);
    });
}
